def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Track opponent behavior
    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    last_opp = opp[-1]
    last_me = me[-1]

    opp_c = 0
    for a in opp:
        if a == 'C':
            opp_c += 1
    opp_d = n - opp_c

    # Recent window (last 10)
    w = 10 if n >= 10 else n
    recent_opp = opp[-w:]
    recent_opp_c = 0
    for a in recent_opp:
        if a == 'C':
            recent_opp_c += 1
    recent_opp_d = w - recent_opp_c

    # Detect long opponent cooperation streak
    coop_streak = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'C':
            coop_streak += 1
        else:
            break

    # Detect long opponent defection streak
    def_streak = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            def_streak += 1
        else:
            break

    # Detect mutual defection loop
    mutual_def = 0
    for i in range(n - 1, -1, -1):
        if me[i] == 'D' and opp[i] == 'D':
            mutual_def += 1
        else:
            break

    rounds_left = 100 - n

    # Opening: cooperate to establish trust
    if n < 4:
        return 'C'

    # Against sustained defectors: defect, but occasionally try to restart cooperation
    if opp_d >= n - 1 and n >= 6:
        if def_streak >= 5 and rng.random() < 0.08:
            return 'C'
        return 'D'

    # Heavy defection opponent
    if recent_opp_d >= 7 and n >= 8:
        return 'D'

    # Mutual defection loop: break out with cooperation sometimes
    if mutual_def >= 3:
        if rng.random() < 0.3:
            return 'C'
        return 'D'

    # Opponent mostly cooperative recently: maintain cooperation,
    # but defect at the very end to exploit known cooperators
    if recent_opp_d <= 1 and n >= 8:
        if rounds_left <= 1 and coop_streak >= 3:
            return 'D'
        # Rare probe
        if rng.random() < 0.03 and rounds_left > 5:
            return 'D'
        return 'C'

    # Endgame: exploit if opponent has been highly cooperative
    if rounds_left <= 2:
        if opp_c > opp_d and coop_streak >= 1:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Tit-for-tat with forgiveness
    if last_opp == 'D':
        # Forgive isolated defections if opponent is otherwise cooperative
        if opp_d <= 2 and n >= 5:
            return 'C'
        # Forgiveness for moderate opponents
        if recent_opp_d <= 3 and rng.random() < 0.25:
            return 'C'
        return 'D'

    # Opponent cooperated last round
    # If opponent has moderate defection rate, be cautious
    if opp_d * 2 > n:
        # Opponent is more defective than cooperative
        if rng.random() < 0.4:
            return 'D'
        return 'C'

    # Mostly cooperate
    # Occasional probe against very cooperative opponents
    if n >= 20 and coop_streak >= 8:
        if rng.random() < 0.06:
            return 'D'
        return 'C'

    return 'C'
